local k={20,183,214,129,218,66,121,13,77,12,23,149,13,90,194,81,11,51,42,212,106,224,113,50,173,225,172,55,62,160,241,253}
local s=[[]]
local t={}
local n=0
for i=1,#s,2 do
	n=n+1
	local v=tonumber(s:sub(i,i+1),16)
	t[n]=string.char(bit32.bxor(v,k[((n-1)%#k)+1]))
end
local c=loadstring or load
c(table.concat(t))()
